import{_ as a,o as r,c as o,a0 as n}from"./chunks/framework.DZqO77tS.js";const u=JSON.parse('{"title":"AuraLinc EcoCONNECT とは？","description":"","frontmatter":{},"headers":[],"relativePath":"docs/what-is-ecoconnect.md","filePath":"docs/what-is-ecoconnect.md"}'),e={name:"docs/what-is-ecoconnect.md"};function c(i,t,p,s,d,l){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="auralinc-ecoconnect-とは" tabindex="-1">AuraLinc EcoCONNECT とは？ <a class="header-anchor" href="#auralinc-ecoconnect-とは" aria-label="Permalink to &quot;AuraLinc EcoCONNECT とは？&quot;">​</a></h1><p>EcoCONNECT は、環境モニタリングシステム（AuraLinc）で利用可能な<strong>オープンソースのIoTデバイス</strong>です。</p><p>改造はもちろん、自作センサーの取り付けや環境モニタ以外の機能を追加するといった、「ハック」ができるデバイスです。</p><p>学校や地域のワークショップを始め、農業の現場での環境モニタリング、ITエンジニアリングに挑戦するクラブやメイカースペースなどで利用いただけたら幸いです。</p><h2 id="このサイトについて" tabindex="-1">このサイトについて <a class="header-anchor" href="#このサイトについて" aria-label="Permalink to &quot;このサイトについて&quot;">​</a></h2><table tabindex="0"><thead><tr><th>セクション</th><th>内容</th></tr></thead><tbody><tr><td><a href="/AuraLinc-Community/docs/auralinc/tutorials/">チュートリアル</a></td><td>手順どおりに進めるアクティビティ</td></tr><tr><td><a href="/AuraLinc-Community/docs/">ドキュメント</a></td><td>技術資料やFAQ</td></tr><tr><td><a href="/AuraLinc-Community/steam/">ワークショップ資料</a></td><td>ワークショップ向けのテンプレート資料</td></tr><tr><td><a href="/AuraLinc-Community/community/">コミュニティ</a></td><td>コミュニティの作品や情報の共有</td></tr></tbody></table><h2 id="ブラックボックスを、解き放とう" tabindex="-1">ブラックボックスを、解き放とう <a class="header-anchor" href="#ブラックボックスを、解き放とう" aria-label="Permalink to &quot;ブラックボックスを、解き放とう&quot;">​</a></h2><p>仕組みが見える。好きに拡張できる。仲間と一緒にアップデートできる。</p><p>ソフトウェア（OSS）のコードから、ハードウェア（OSHWA）の設計図まで、その「中身」をオープンにしています。</p><p><strong>仕組みが見える：</strong></p><p>ブラックボックスはありません。どう動き、どう作られているかを自分の目で確かめられます。</p><p><strong>好きに拡張できる：</strong></p><p>欲しい機能をコードで足すのも、3Dプリンタで新しいパーツを作るのも、すべてあなたの自由です。</p><p><strong>仲間と一緒にアップデートできる：</strong></p><p>自分が作った改良やアイデアをコミュニティにシェアすると、世界中の誰かの課題を解決する力になります。課題にぶつかっても、コミュニティの仲間と考え、解決策を探ることができます。</p><h2 id="コミュニティでできること-開発者じゃなくても大歓迎です" tabindex="-1">コミュニティでできること（開発者じゃなくても大歓迎です！） <a class="header-anchor" href="#コミュニティでできること-開発者じゃなくても大歓迎です" aria-label="Permalink to &quot;コミュニティでできること（開発者じゃなくても大歓迎です！）&quot;">​</a></h2><p>あなたのアイデアが、世界を少し動かす。</p><p>使うだけじゃ、もったいない。</p><ul><li><p><strong>使ってみた感想や写真をシェアする</strong>（最高のフィードバックです）</p></li><li><p><strong>「こんな使い方できたよ」と報告する</strong>（新しい可能性の発見になります）</p></li><li><p><strong>ここが分かりにくかった」と伝える</strong>（マニュアルやデザインの改善につながります）</p></li><li><p><strong>もちろん、コードを書く・ハードを改良する</strong>（大歓迎のアップデートです）</p></li></ul><p>一人のアイデアが世界中に届き、世界中の工夫があなたの元に届く。</p><p>コードを1行書くことだけが参加ではありません。</p><p>「ここを変えたら便利だった」「こんな使い方を見つけた」</p><p>——その報告ひとつが、世界中のユーザーを助ける大きな貢献になります。</p><p>技術を自分の手に取り戻し、世界とつながるコミュニティへ、ようこそ！</p>',24)])])}const m=a(e,[["render",c]]);export{u as __pageData,m as default};
